package com.example.birthday.chatservice.service;
import com.example.birthday.chatservice.client.UserClient; import com.example.birthday.chatservice.dto.*; import com.example.birthday.chatservice.exception.BusinessException; import com.example.birthday.chatservice.mapper.ChatMapper; import com.example.birthday.chatservice.model.*; import com.example.birthday.chatservice.repository.*; import com.example.birthday.chatservice.service.impl.ChatServiceImpl; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.mapstruct.factory.Mappers; import java.util.*; import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.Mockito.when;
@ExtendWith(MockitoExtension.class) class ChatServiceImplTest{
 @Mock ChatRoomRepository rooms;@Mock ChatParticipantRepository participants;@Mock ChatMessageRepository messages;@Mock UserClient users;@Mock ChatMessageDeliveryService delivery;ChatServiceImpl service;
 @BeforeEach void setup(){service=new ChatServiceImpl(rooms,participants,messages,users,Mappers.getMapper(ChatMapper.class),delivery);}
 @Test void cannotCreateChatAboutSelf(){UUID u=UUID.randomUUID();assertThatThrownBy(()->service.createBirthday(u,u,new CreateChatRequest("Self"))).isInstanceOf(BusinessException.class).hasMessage("User cannot create a birthday chat about self");}
 @Test void birthdayPersonCannotJoin(){UUID target=UUID.randomUUID(),roomId=UUID.randomUUID();var room=new ChatRoom();room.setTargetUserId(target);when(rooms.findByIdAndDeletedAtIsNull(roomId)).thenReturn(Optional.of(room));assertThatThrownBy(()->service.join(target,roomId)).isInstanceOf(BusinessException.class).hasMessage("Birthday person cannot access this chat");}
}
